guidance.correct_example:
from datetime import datetime

def create_timestamp(a_now: datetime | None = None) -> Result[str]:
    now = a_now or datetime.now()
    return Result.success(now.isoformat())

guidance.incorrect_example:
from datetime import datetime

def create_timestamp() -> Result[str]:
    now = datetime.now()
    return Result.success(now.isoformat())
